import { saveAs } from "file-saver";

// Replace with your actual full Base64 Data URI string for your PDF encryption document
// Standard PDF Base64 strings almost always begin with "JVBERi0xLj..." (which decodes to "%PDF-1.")
export const STATIC_ENCRYPTION_DOC_BASE64 =
  "data:application/pdf;base64,";

export const downloadStaticFile = (base64DataUri: string, defaultFileName: string) => {
  try {
    const parts = base64DataUri.split(",");
    const byteString = atob(parts[1] || parts[0]);
    const mimeString = parts[0].split(":")[1]?.split(";")[0] || "application/pdf";

    const ab = new ArrayBuffer(byteString.length);
    const ia = new Uint8Array(ab);
    for (let i = 0; i < byteString.length; i++) {
      ia[i] = byteString.charCodeAt(i);
    }

    const blob = new Blob([ab], { type: mimeString });
    saveAs(blob, defaultFileName);
  } catch (error) {
    console.error("Failed to trigger static download:", error);
    alert("Unable to download static file. Ensure Base64 string is formatted correctly.");
  }
};